full[0]['related']+=['hunters','skill-synthesis','duo-races','ananke','eschaton']
# Both mods share only the content they actually register.
for mod,entries,folder in [('wildhunt',full,ROOT/'src/main/resources/assets/wildhunt'),('heavenlyrestriction',common,ROOT/'standalone/tensura-additional-additions/src/main/resources/assets/heavenlyrestriction')]:
    import copy
    entries=copy.deepcopy(entries)
    if mod=='heavenlyrestriction':
        entries.append({'id': 'loan-shark', 'title': 'Loan Shark', 'category': 'Skills', 'summary': 'Unique · Lend skill copies with retained mastery. Transfer 25% of EP gains, stacking with diminishing returns for additional active gifts.', 'icon': 'heavenlyrestriction:textures/skill/loan_shark.png', 'keywords': ['loan', 'gift', 'claim', 'debt', 'skill stealing', 'report', 'EP'], 'related': ['fusion', 'chained'], 'sections': [{'title': 'Loan', 'lines': ['Aim at your subordinate or a player within 16 blocks, then press Loan. Search your owned skills and send a gift. Players must accept; subordinate gifts are immediate. The original skill stays yours.', 'Copies retain mastery, learned mode progress and current cooldowns. They do not clone stored inventories/banks or active effects. Already-owned skills cannot be overwritten; temporary/sub-abilities and Loan Shark itself cannot be lent.']}, {'title': 'Income and usage', 'lines': ['Active gifts transfer 25% of new permanent EP for one gift, 43.75% for two, 57.8125% for three and 68.359375% for four. Each additional gift takes 25% of the remaining gain; the total approaches 100% without exceeding it. Count only gifts in use on that borrower; share the total equally among active gifts, including different lenders. Current-resource regeneration is not EP. Offline lenders receive queued credit on return.', 'Casting/channeling and attributed hits count as use; toggles count while enabled, native ticking passives while ticking, and detected in-slot passives while equipped. Resistances are continuously active while owned. Brief casts/hits use a one-second activity window.']}, {'title': 'Report and Claim', 'lines': ['Search by skill or borrower. Inspect EP transferred, total use time, current idle time, and last/longest idle gaps. Unloaded/online-unavailable borrowers cannot be claimed.', 'Claim always recalls the gifted copy. After at least 10 uninterrupted minutes idle, and only if still idle, it also removes a random eligible unowned skill from the borrower and gives it to you with mastery retained. Chained and every Ultimate-classified skill are excluded from theft.', 'Claim sooner or while active only recalls the copy. A closed contract cannot be claimed twice. Existing independent skill ownership is protected.']}]})
        entries.append({'id': 'exponentiation', 'title': 'Exponentiation', 'category': 'Skills', 'summary': 'Unique · In-slot passive. Square supported beneficial values; movement is excluded.', 'icon': 'heavenlyrestriction:textures/skill/exponentiation.png', 'keywords': ['square', 'squared', 'attack speed', 'chant speed', 'mining', 'beneficial', 'final damage'], 'related': ['prospector', 'schema', 'chained'], 'sections': [{'title': 'Use', 'lines': ['Learn Exponentiation and equip it in the current Tensura skill preset. No toggle, resource cost or cooldown. Owning it or putting it in an inactive preset does not activate it.']}, {'title': 'Affected', 'lines': ['Final outgoing HP/SHP damage; HP/SHP healing; aura and magicule recovery; resource recovery; total kill EP awards before the normal race split; learning and mastery gains; XP and block/mob drop stack quantities.', 'Beneficial attributes: non-energy capacities, attack damage and speed, mining and chant speed, armor, barriers, elemental boosts/resistances, chances, senses, reach and other supported non-movement attributes.']}, {'title': 'Rules and limits', 'lines': ['Each output is squared once. Formula inputs are read normally while calculating damage, recovery, mining and point gains. Saved base stats are not repeatedly squared. Maximum HP, SHP, absorption, oxygen and water/lava capacities are squared; maximum aura and magicules stay normal. Maximum air supply is also squared: 15 seconds becomes 225 seconds (4,500 ticks), without an instant refill.', 'Values of 1 or less are retained so fractions are not weakened. Chances stop at their native maximum; drops stop at each item’s normal stack size; finite number limits apply. Chained’s locked magicule cap remains locked.']}, {'title': 'Excluded', 'lines': ['All movement: running, flying, swimming, sneaking, jumping, dashes, teleports, knockback and body size. Attack speed, mining speed and chant speed ARE included.', 'No squaring of costs, cooldowns, incoming damage, progression requirements, recipe outputs, enchantment levels or fixed skill constants such as duration/radius. The web wiki lists exact native attribute IDs.']}]})
        entries.append(entry('parallel-world-jumper','Parallel World Jumper','Skills','Unique skill · Single-player only. Press World Hop to enter a fresh-seed continuation.',section('World Hop','Every dimension regenerates. Your character, inventory and progression carry over. The game saves, closes and reloads your world during the hop. No aura or magicule cost.'),section('Arrival','Land on the nearest safe ground around your previous coordinates. If there is no nearby safe ground, World Hop searches around the Overworld spawn instead.'),section('Previous world','Builds, terrain and entities stay in the previous world, which remains in the Singleplayer list. Terrain maps and bed/spawn bindings reset in the new continuation. World generator presets and datapacks are preserved; flat presets remain flat.'),section('Obtaining','Can roll as a reincarnation Unique in a private single-player world. Cannot be acquired, copied, learned or used on dedicated servers or while open to LAN. Chained must receive it through reincarnation to permit it.'),keywords=['world hop','new seed','regenerate','parallel'],icon='tensura:textures/skill/extra/spatial_motion.png'))
    allowed={e['id'] for e in entries}
    for e in entries:
        e['related']=[i for i in e['related'] if i in allowed]
        if mod=='heavenlyrestriction':
            if e['id']=='schema':e['summary']='Obtain Schema from Tensura’s Battlewill Manual random pool. Learn: 1,000 points. Master: 2,000 points. It no longer appears automatically.'
            e['icon']=e['icon'].replace('wildhunt:','heavenlyrestriction:')
            e['summary']=e['summary'].replace('hunter or Heavenly Restriction','Heavenly Restriction')
            for sec in e['sections']:sec['lines']=[l.replace('hunter or Heavenly Restriction','Heavenly Restriction') for l in sec['lines']]
        icon=e['icon']
        if icon.startswith(mod+':') and not (folder/icon.split(':',1)[1]).is_file():e['icon']='minecraft:textures/item/book.png'
    # IDs must be unique and related links always resolvable.
    assert len(allowed)==len(entries),(mod,'duplicate IDs')
    for e in entries:
        assert e['summary'] and e['sections'],e['id']
        assert all(i in allowed for i in e['related'])
    target=folder/'guide/entries.json';target.parent.mkdir(parents=True,exist_ok=True);target.write_text(json.dumps({'entries':entries},ensure_ascii=False,indent=2)+'\n')
    print(mod,len(entries),'pages')
